<script setup lang="ts">
import PaymentAttemptHistory, {type PaymentAttempt} from '../../components/tenant/PaymentAttemptHistory.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsoleQueryButton from '../../components/console/ConsoleQueryButton.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import {dateTime} from '../../utils/update-center'
definePageMeta({layout:'tenant',key:route=>route.path})
type Order={paymentAttempts?:PaymentAttempt[];id:string;userId:string;kind:string;name:string;amountCents:number;refundedCents:number;status:string;createdAt:string;product:{base:number;gift:number;asset:string};payment:{provider:string;state:string;paidAt:string|null;payerTotalCents:number|null}|null;refundUnavailableReason:string|null}
type Listing={items:Order[];total:number;page:number;pageSize:number;applicationKey:string;canManage:boolean}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/recharge-orders',q=ref(''),search=ref(''),status=ref('all'),appliedStatus=ref('all'),page=ref(1),busy=ref(''),error=ref(''),detail=ref<Order|null>(null),refundOrder=ref<Order|null>(null),refundAmount=ref(''),reason=ref(''),refundBusy=ref(false),refundError=ref(''),attempt=ref<any>(null)
const params=()=>new URLSearchParams({q:search.value,status:appliedStatus.value,page:String(page.value),pageSize:'20'})
const initial=await useAsyncData<Listing>('recharge-orders:'+auth.session.value?.id+':'+tenantId,(_,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal})),rows=ref<Listing>(initial.data.value||{items:[],total:0,page:1,pageSize:20,applicationKey:'',canManage:false});error.value=initial.error.value?.message||''
const columns=[{id:'name',header:'充值订单'},{id:'amount',header:'金额（元）'},{id:'payment',header:'支付方式'},{id:'status',header:'状态'},{id:'createdAt',header:'创建时间'},{id:'actions',header:'操作'}],labels:Record<string,string>={pending:'待付款',paid:'已支付',cancelled:'已取消',refunded:'已退款',partial_refund:'部分退款',refund_pending:'退款处理中',compensation_due:'待补偿'},lifetime=new AbortController();let controller:AbortController|undefined,sequence=0,disposed=false
const paymentLabels:Record<string,string>={balance:'余额支付',wechat:'微信支付',alipay:'支付宝','wechat-virtual':'微信虚拟支付'}
const paymentLabel=(provider?:string)=>provider?paymentLabels[provider]||'未知方式':'—'
const money=(n:number)=>Math.trunc(n/100)+'.'+String(n%100).padStart(2,'0')
async function load(source='refresh'){if(disposed)return;controller?.abort();controller=new AbortController();const current=++sequence;busy.value=source;try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,controller.signal])});if(!disposed&&current===sequence){rows.value=value;page.value=value.page;error.value=''}}catch(e:any){if(!disposed&&current===sequence)error.value=e.message||'读取失败'}finally{if(!disposed&&current===sequence)busy.value=''}}
function filter(source:'search'|'reset'){if(source==='reset'){q.value='';status.value='all'}search.value=q.value.trim();appliedStatus.value=status.value;page.value=1;void load(source)}
function setPage(value:number){if(value===page.value)return;page.value=value;void load('page')}
function askRefund(row:Order){if(refundBusy.value||row.refundUnavailableReason)return;refundOrder.value=row;refundAmount.value=money(row.amountCents-row.refundedCents);reason.value='';refundError.value='';attempt.value=null}
async function submitRefund(){if(!refundOrder.value||refundBusy.value)return;if(!attempt.value){if(!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(refundAmount.value)||!reason.value.trim()){refundError.value='请输入有效金额和退款原因';return}const [whole,fraction='']=refundAmount.value.split('.'),amountCents=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(amountCents<1||amountCents>refundOrder.value.amountCents-refundOrder.value.refundedCents){refundError.value='退款金额超过剩余可退金额';return}attempt.value={amountCents,reason:reason.value.trim(),requestKey:crypto.randomUUID()}}
 refundBusy.value=true;refundError.value='';try{await auth.api('/admin/tenants/'+encodeURIComponent(tenantId)+'/recharge-orders/'+encodeURIComponent(rows.value.applicationKey)+'/'+refundOrder.value.id+'/refund','POST',attempt.value,{signal:lifetime.signal});if(!disposed){refundOrder.value=null;attempt.value=null;await load('mutation')}}catch(e:any){if(!disposed){refundError.value=e.message||'结果待确认，请使用原请求重试';if(e.status&&e.status<500)attempt.value=null}}finally{if(!disposed)refundBusy.value=false}}
onBeforeRouteLeave(()=>!refundBusy.value&&!attempt.value)
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort()})
</script>
<template><AdminConsole :refreshing="busy==='refresh'" @refresh="load()"><div class="space-y-5"><ConsolePageHeading title="充值订单"/>
 <form @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索订单号或账号"/><USelect v-model="status" :items="[{label:'全部状态',value:'all'},...['pending','paid','refunded','cancelled'].map(value=>({label:labels[value],value}))]" aria-label="订单状态"/><div class="flex gap-3"><ConsoleQueryButton type="submit" :loading="busy==='search'">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="busy==='reset'" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable :data="rows.items" :columns="columns" :total="rows.total" :page="page" :page-size="20" :client-pagination="false" :error="error" empty-title="暂无充值订单" min-table-width="800px" @retry="load('retry')" @update:page="setPage"><template #name-cell="{row}"><div><p class="font-medium">{{row.original.name}}</p><p class="text-xs text-muted">{{row.original.id}}</p><p class="text-xs text-muted">{{row.original.userId}}</p></div></template><template #amount-cell="{row}"><span class="tabular-nums">{{money(row.original.amountCents)}}</span><p v-if="row.original.refundedCents" class="text-xs text-muted">已退 {{money(row.original.refundedCents)}}</p></template><template #payment-cell="{row}"><span class="whitespace-nowrap">{{paymentLabel(row.original.payment?.provider)}}</span></template><template #status-cell="{row}">{{labels[row.original.status]||row.original.status}}</template><template #createdAt-cell="{row}">{{dateTime(row.original.createdAt)}}</template><template #actions-cell="{row}"><div class="flex gap-3 whitespace-nowrap"><UButton variant="link" class="px-0" @click="detail=row.original">查看详情</UButton><UButton v-if="rows.canManage&&['paid','partial_refund','compensation_due'].includes(row.original.status)" variant="link" class="px-0" :disabled="!!row.original.refundUnavailableReason||refundBusy" :title="row.original.refundUnavailableReason||''" @click="askRefund(row.original)">退款</UButton></div><p v-if="row.original.refundUnavailableReason&&row.original.status==='paid'" class="max-w-56 whitespace-normal text-xs text-muted">{{row.original.refundUnavailableReason}}</p></template></ConsoleDataTable>
 <ConsoleDrawer :open="!!detail" title="充值订单详情" @update:open="!$event&&(detail=null)"><template #body><dl v-if="detail" class="drawer-facts"><dt>状态</dt><dd>{{labels[detail.status]||detail.status}}</dd><dt>订单号</dt><dd>{{detail.id}}</dd><dt>账号</dt><dd>{{detail.userId}}</dd><dt>类型</dt><dd>{{detail.kind==='points_recharge'?'积分套餐充值':'人民币余额充值'}}</dd><dt>应付金额</dt><dd>¥ {{money(detail.amountCents)}}</dd><dt>基础到账</dt><dd>{{detail.product.asset==='points'?detail.product.base+' 积分':'¥ '+money(detail.product.base)}}</dd><dt>赠送</dt><dd>{{detail.product.asset==='points'?detail.product.gift+' 积分':'¥ '+money(detail.product.gift)}}</dd><dt>支付方式</dt><dd>{{paymentLabel(detail.payment?.provider)}}</dd><dt>实付金额</dt><dd>{{detail.payment?.payerTotalCents==null?'—':'¥ '+money(detail.payment.payerTotalCents)}}</dd><dt>创建时间</dt><dd>{{dateTime(detail.createdAt)}}</dd><dt>支付时间</dt><dd>{{dateTime(detail.payment?.paidAt)}}</dd></dl><PaymentAttemptHistory v-if="detail?.paymentAttempts" :items="detail.paymentAttempts"/></template></ConsoleDrawer>
 <ConsoleDrawer :open="!!refundOrder" title="订单退款" :dismissible="!refundBusy&&!attempt" @update:open="!$event&&!refundBusy&&!attempt&&(refundOrder=null)"><template #body><form id="recharge-refund" class="space-y-5" @submit.prevent="submitRefund"><UAlert v-if="refundError" color="error" :title="refundError"/><p class="text-sm text-muted">仅未消费或调整的充值支持自动退款。首次退款会收回该订单全部到账资产，后续退余款不重复回收。</p><ConsoleSettingsField label="退款金额（元）"><ConsoleInput v-model="refundAmount" inputmode="decimal" required :disabled="refundBusy||!!attempt"/></ConsoleSettingsField><ConsoleSettingsField label="退款原因"><UTextarea v-model="reason" required :maxlength="200" class="w-full" :disabled="refundBusy||!!attempt"/></ConsoleSettingsField><p v-if="attempt&&!refundBusy" role="status">原请求结果待确认，请重试查询原操作。</p></form></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="refundBusy||!!attempt" @click="refundOrder=null">取消</UButton><UButton form="recharge-refund" type="submit" :loading="refundBusy">{{attempt?'查询原操作':'确认退款'}}</UButton></ConsoleFormActions></template></ConsoleDrawer>
</div></AdminConsole></template>
